look.customCSS:
/* ───── 折角便签 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScxOCcgaGVpZ2h0PScxOCcgdmlld0JveD0nMCAwIDE4IDE4Jz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4xJyBmaWxsPScjRDNDQ0UyJy8+PGNpcmNsZSBjeD0nMTInIGN5PScxMicgcj0nMS4xJyBmaWxsPScjRDNDQ0UyJy8+PC9zdmc+") 0 0/18px 18px,#EEEAF5 !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：米白便签条，右下折一个角 */
[data-wk="chathead"]{background:#FFFFFF !important;border-bottom:1.4px solid #3F3A52 !important;box-shadow:0 2px 0 rgba(74,68,88,.08) !important;position:relative !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;right:0 !important;bottom:-1.4px !important;width:16px !important;height:16px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTAgMCBIMjAgVjIwWicgZmlsbD0nI0VFRUFGNScvPjxwYXRoIGQ9J00wIDAgTDIwIDIwIEgwWicgZmlsbD0nI0ZCRkFGRScgc3Ryb2tlPScjM0YzQTUyJyBzdHJva2Utd2lkdGg9JzEuNCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important;transform:scaleY(-1) !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#3F3A52 !important}
[data-wk="headdim"]{color:#9A93AE !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chatback"] svg{stroke:#3F3A52 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：方的，右上折一个小角 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="chathead"] img{border-radius:2px !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),[data-wk="chathead"] [data-wk="avatar"]{box-shadow:0 0 0 1.4px #3F3A52,3px 3px 0 rgba(63,58,82,.16) !important;position:relative !important;overflow:visible !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;right:-1.4px !important;top:-1.4px !important;width:12px !important;height:12px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTAgMCBIMjAgVjIwWicgZmlsbD0nI0VFRUFGNScvPjxwYXRoIGQ9J00wIDAgTDIwIDIwIEgwWicgZmlsbD0nI0ZCRkFGRScgc3Ryb2tlPScjM0YzQTUyJyBzdHJva2Utd2lkdGg9JzEuNCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important}

/* 便签气泡：方角、细线、右下一道淡影；每串第一条折右上角，后面几条折左上角，像一叠便签 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:1.4px solid #3F3A52 !important;border-radius:2px !important;box-shadow:3px 3px 0 rgba(63,58,82,.16) !important;color:#3F3A52 !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#D8CEF0 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFFFF !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;right:-1.4px !important;left:auto !important;top:-1.4px !important;bottom:auto !important;width:14px !important;height:14px !important;border:none !important;transform:none !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTAgMCBIMjAgVjIwWicgZmlsbD0nI0VFRUFGNScvPjxwYXRoIGQ9J00wIDAgTDIwIDIwIEgwWicgZmlsbD0nI0ZCRkFGRScgc3Ryb2tlPScjM0YzQTUyJyBzdHJva2Utd2lkdGg9JzEuNCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PHBhdGggZD0nTTAgMCBIMjAgVjIwWicgZmlsbD0nI0VFRUFGNScvPjxwYXRoIGQ9J00wIDAgTDIwIDIwIEgwWicgZmlsbD0nI0ZCRkFGRScgc3Ryb2tlPScjM0YzQTUyJyBzdHJva2Utd2lkdGg9JzEuNCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-first="0"] [data-wk="bubble"][data-kind="text"]::before{right:auto !important;left:-1.4px !important;transform:scaleX(-1) !important}

/* 时间：一行等宽小字，两边【】 */
[data-wk="time"] > span{background:transparent !important;border:none !important;color:#3F3A52 !important;font-family:ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;font-size:11px !important}
[data-wk="time"] > span::before{content:"【 " !important}
[data-wk="time"] > span::after{content:" 】" !important}
/* 已读：一行小字，已读后面一个淡金小勾 */
[data-wk="meta"]{color:#9A93AE !important;font-family:ui-monospace,Menlo,monospace !important;font-size:10.5px !important;letter-spacing:.08em !important}
[data-wk="meta"][data-read="1"]::after{content:"" !important;display:inline-block !important;width:11px !important;height:9px !important;margin-left:4px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCAxMic+PHBhdGggZD0nTTEuNSA2LjUgTDUgMTAgTDEyLjUgMicgZmlsbD0nbm9uZScgc3Ryb2tlPScjNkI1QkE4JyBzdHJva2Utd2lkdGg9JzInIHN0cm9rZS1saW5lY2FwPSdyb3VuZCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#9A93AE !important;font-family:ui-monospace,Menlo,monospace !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFFFF !important;border:1.4px solid #3F3A52 !important;border-radius:2px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#3F3A52 !important}
/* 动描：一行斜体，左边一道淡金竖线 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:transparent !important;border:none !important;border-left:2px solid #6B5BA8 !important;border-radius:0 !important;box-shadow:none !important;color:#3F3A52 !important;opacity:.8 !important;font-style:italic !important;font-size:13px !important;padding:2px 0 2px 12px !important}
/* 系统提示：不带框的一行小字 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9A93AE !important;font-size:11.5px !important;font-style:normal !important}

/* 底栏：米白便签条；左加号、发送，右边回复是一张折角小便签 */
[data-wk="composer"]{background:#FFFFFF !important;border-top:1.4px solid #3F3A52 !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#fff !important;border:1.4px solid #3F3A52 !important;border-radius:2px !important;color:#3F3A52 !important}
[data-wk="chatinput"]::placeholder{color:#9A93AE !important}
[data-wk="chatplus"],[data-wk="send"]{width:32px !important;min-width:32px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAzMCc+PHBhdGggZD0nTTE1IDI0IFY4IE05IDE0IEwxNSA4IEwyMSAxNCcgZmlsbD0nbm9uZScgc3Ryb2tlPScjM0YzQTUyJyBzdHJva2Utd2lkdGg9JzInIHN0cm9rZS1saW5lY2FwPSdyb3VuZCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/26px no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:52px !important;min-width:52px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(2px 3px 0 rgba(74,68,88,.14)) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}

/* 照参考图：折角只在每串第一条——我的折右上、他的折左上；后面几条不折。折过来那块是白的 */
[data-first="0"] [data-wk="bubble"][data-kind="text"]::before{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{right:auto !important;left:-1.4px !important;transform:scaleX(-1) !important}
[data-wk="msg"][data-me="0"] button[data-wk="avatar"]::after,[data-wk="cardrow"][data-me="0"] button[data-wk="avatar"]::after{right:auto !important;left:-1.4px !important;transform:scaleX(-1) !important}
[data-wk="msg"][data-me="0"] span[data-wk="avatar"]::after{right:auto !important;left:-1.4px !important;transform:scaleX(-1) !important}
/* 已读：紫色勾放在前面 */
[data-wk="meta"][data-read="1"]::after{content:none !important}
[data-wk="meta"]::before{content:"" !important;display:inline-block !important;width:12px !important;height:10px !important;margin-right:4px !important;vertical-align:-1px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCAxMic+PHBhdGggZD0nTTEuNSA2LjUgTDUgMTAgTDEyLjUgMicgZmlsbD0nbm9uZScgc3Ryb2tlPScjNkI1QkE4JyBzdHJva2Utd2lkdGg9JzInIHN0cm9rZS1saW5lY2FwPSdyb3VuZCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]::before{order:2 !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{display:inline-flex !important;flex-direction:row-reverse !important;gap:4px !important}
/* 底栏：输入框淡紫，发送是深紫折角方块白箭头 */
[data-wk="chatinput"]{background:#F3EFFA !important}
[data-wk="send"]{order:99 !important;width:40px !important;min-width:40px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(3px 3px 0 rgba(63,58,82,.16)) !important}

[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
